INSERT INTO `resources` (`id`, `category_id`, `title`, `title_ar`, `slug`, `resource_type`, `tech_stack`, `tech_stack_ar`, `description`, `description_ar`, `features`, `features_ar`, `short_description`, `short_description_ar`, `preview_image`, `detail_image`, `screenshots`, `featured`, `is_free`, `price`, `version`, `license`, `downloads_count`, `rating`, `reviews_count`, `published_at`, `status`, `demo_url`, `created_at`, `updated_at`) VALUES
(1, 1, 'Travelix', 'ترافيلكس - قالب وكالات السفر والسياحة', 'travelix', 'website', 'Next.js 15, Tailwind CSS, TypeScript, Supabase', 'HTML5, Tailwind CSS, JavaScript', '<p><strong>Travelix Pro</strong> is the premier solution for modern travel agencies worldwide.</p><ul><li>Instant Booking Engine</li><li>Interactive Map Views</li></ul>', '<p>ترافيلكس هو قالب عصري فائق الأناقة تم تصميمه خصيصاً لوكالات السفر وشركات السياحة وحجوزات الطيران والفنادق. يتميز بتصميم متجاوب بالكامل وتجربة مستخدم سلسة.</p>', '[\"Instant Tour Booking Engine\",\"Interactive Destination Maps\",\"Multi-currency Support\",\"SEO & Mobile Optimized\"]', '[\"\\u062a\\u0635\\u0645\\u064a\\u0645 \\u0645\\u062a\\u062c\\u0627\\u0648\\u0628 \\u0628\\u0627\\u0644\\u0643\\u0627\\u0645\\u0644\",\"\\u062f\\u0639\\u0645 \\u0627\\u0644\\u0648\\u0636\\u0639 \\u0627\\u0644\\u062f\\u0627\\u0643\\u0646 \\u0648\\u0627\\u0644\\u0641\\u0627\\u062a\\u062d\",\"\\u0646\\u0638\\u0627\\u0645 \\u062d\\u062c\\u0632 \\u0648\\u062a\\u0635\\u0641\\u064a\\u0629 \\u0631\\u062d\\u0644\\u0627\\u062a \\u0645\\u062a\\u0642\\u062f\\u0645\",\"\\u0633\\u0647\\u0648\\u0644\\u0629 \\u0627\\u0644\\u062a\\u062e\\u0635\\u064a\\u0635 \\u0648\\u0627\\u0644\\u0623\\u0643\\u0648\\u0627\\u062f \\u0627\\u0644\\u0646\\u0638\\u064a\\u0641\\u0629\"]', 'Ultra Luxury Travel & Tourism Portal', 'قالب موقع حديث ومتكامل لوكالات السفر وحجوزات الفنادق والرحلات.', '/assets/travelix-card.png', '/assets/travelix-detail.png', '[\"\\/assets\\/travelix-detail.png\",\"\\/assets\\/travelix.png\",\"\\/assets\\/travelix-card.png\"]', 1, 1, '0.00', '2.1.0', 'Extended Commercial License', 0, '0.0', 0, '2026-09-08 18:54:41', 'published', 'https://travelix-demo.example.com', '2026-09-08 18:54:41', '2026-09-11 23:29:01'),
(2, 1, 'SaaSPro', 'ساس برو - قالب لشركات البرمجيات والشركات الناشئة', 'saaspro', 'website', 'React, Next.js, Tailwind CSS, Framer Motion', 'Next.js 15, React, Tailwind CSS', '<p><strong>SaaSPro</strong> delivers a conversion-optimized layout designed to showcase modern software, developer tools, and cloud platforms.</p><h3>Why choose SaaSPro?</h3><ul><li>Clean typography with rich gradients and subtle glassmorphism effects.</li><li>Fully animated interactive elements powered by Framer Motion.</li><li>Includes landing page, feature breakdown, integrations page, and pricing matrix.</li></ul>', '<p>ساس برو مصمم خصيصاً للشركات الناشئة ومنصات SaaS لعرض مميزات التطبيق، خطط الأسعار، وآراء العملاء بأعلى معدلات تحويل.</p>', '[\"High-converting SaaS Landing Page\",\"Dark & Light Mode Color Themes\",\"Interactive Pricing Calculator with Monthly\\/Annual toggle\",\"Feature comparison tables & FAQ accordions\"]', '[\"\\u062c\\u062f\\u0627\\u0648\\u0644 \\u0623\\u0633\\u0639\\u0627\\u0631 \\u0645\\u062a\\u0641\\u0627\\u0639\\u0644\\u0629\",\"\\u0633\\u064a\\u0643\\u0634\\u0646 \\u0627\\u0644\\u0645\\u0642\\u0627\\u0631\\u0646\\u0629 \\u0648\\u0622\\u0631\\u0627\\u0621 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u0621\",\"\\u0645\\u0643\\u0648\\u0646\\u0627\\u062a \\u0645\\u062a\\u0648\\u0627\\u0641\\u0642\\u0629 \\u0645\\u0639 SEO\",\"\\u0623\\u062f\\u0627\\u0621 \\u0641\\u0627\\u0626\\u0642 \\u0648\\u0633\\u0631\\u0639\\u0629 \\u062a\\u062d\\u0645\\u064a\\u0644 \\u0645\\u0630\\u0647\\u0644\\u0629\"]', 'Startup Landing Template', 'صفحة هبوط احترافية وعصرية للترويج لتطبيقات الويب والخدمات السحابية.', '/assets/saaspro-card.png', '/assets/saaspro.png', '[\"\\/assets\\/saaspro.png\",\"\\/assets\\/saaspro-card.png\"]', 1, 1, '0.00', '1.0.0', 'Free for Personal & Commercial Use', 0, '0.0', 0, '2026-09-07 18:54:41', 'published', NULL, '2026-09-08 18:54:41', '2026-09-11 23:29:01'),
(3, 1, 'ShopMart', 'شوب مارت - قالب متجر إلكتروني متكامل', 'shopmart', 'website', 'Next.js, Tailwind CSS, Zustand, Stripe Ready', 'React, Next.js, Tailwind CSS', '<p><strong>ShopMart</strong> is a blazing fast eCommerce template crafted for modern online retailers and brands.</p><h3>What is included:</h3><ul><li>Multi-category product catalog with price, rating, and brand filtering.</li><li>Instant cart sliding drawer with quantity adjustments.</li><li>Clean checkout and order confirmation mockups.</li></ul>', '<p>شوب مارت يمنحك تجربة تسوق متكاملة مع صفحات المنتجات، سلة المشتريات، وإتمام الطلب بتصميم أنيق وعصري.</p>', '[\"Modern eCommerce Storefront & Catalog\",\"Slide-over Shopping Cart & Drawer\",\"Fast Product Filtering & Search\",\"Mobile-first responsive design\"]', '[\"\\u0633\\u0644\\u0629 \\u0645\\u0634\\u062a\\u0631\\u064a\\u0627\\u062a \\u062a\\u0641\\u0627\\u0639\\u0644\\u064a\\u0629\",\"\\u0641\\u0644\\u062a\\u0631\\u0629 \\u0648\\u0628\\u062d\\u062b \\u0641\\u0648\\u0631\\u064a \\u0639\\u0646 \\u0627\\u0644\\u0645\\u0646\\u062a\\u062c\\u0627\\u062a\",\"\\u062a\\u0635\\u0645\\u064a\\u0645 \\u0645\\u062e\\u0635\\u0635 \\u0644\\u0644\\u0645\\u0648\\u0628\\u0627\\u064a\\u0644 \\u0648\\u0627\\u0644\\u062a\\u0627\\u0628\\u0644\\u062a\",\"\\u062c\\u0627\\u0647\\u0632 \\u0644\\u0644\\u0631\\u0628\\u0637 \\u0645\\u0639 \\u0628\\u0648\\u0627\\u0628\\u0627\\u062a \\u0627\\u0644\\u062f\\u0641\\u0639\"]', 'eCommerce Template', 'قالب متجر إلكتروني عصري لعرض وبيع المنتجات بسلاسة وسرعة.', '/assets/shopmart-card.png', '/assets/shopmart.png', '[\"\\/assets\\/shopmart.png\",\"\\/assets\\/shopmart-card.png\"]', 1, 1, '0.00', '1.0.0', 'Free for Personal & Commercial Use', 0, '0.0', 0, '2026-09-06 18:54:41', 'published', NULL, '2026-09-08 18:54:41', '2026-09-11 23:29:01'),
(4, 1, 'DashForge', 'داش فورج - لوحة تحكم إدارية حديثة', 'dashforge', 'website', 'Tailwind CSS, Alpine.js, Chart.js', 'React, Chart.js, Tailwind CSS', '<p><strong>DashForge</strong> is a clean, versatile administrative dashboard template built for enterprise SaaS, analytics platforms, and internal business tools.</p><h3>Features Overview:</h3><ul><li>Real-time chart components for traffic, revenue, and conversion tracking.</li><li>Responsive sidebar navigation with multi-level submenus.</li><li>Ready-to-use form layouts, modal dialogs, and toast notifications.</li></ul>', '<p>داش فورج توفر للمطورين كافة المكونات اللازمة لبناء لوحات تحكم SaaS وإدارة المستخدمين والإحصائيات بدقة عالية.</p>', '[\"Comprehensive Admin Dashboard Layout\",\"Interactive Charts & Live KPI widgets\",\"Sortable Data Tables & Filter Bars\",\"Pre-built Auth & User Management Pages\"]', '[\"\\u0623\\u0643\\u062b\\u0631 \\u0645\\u0646 30 \\u0635\\u0641\\u062d\\u0629 \\u0648\\u0645\\u0643\\u0648\\u0646 \\u062c\\u0627\\u0647\\u0632\",\"\\u0645\\u062e\\u0637\\u0637\\u0627\\u062a \\u0628\\u064a\\u0627\\u0646\\u064a\\u0629 \\u062a\\u0641\\u0627\\u0639\\u0644\\u064a\\u0629\",\"\\u0625\\u062f\\u0627\\u0631\\u0629 \\u0627\\u0644\\u0645\\u0633\\u062a\\u062e\\u062f\\u0645\\u064a\\u0646 \\u0648\\u0627\\u0644\\u0635\\u0644\\u0627\\u062d\\u064a\\u0627\\u062a\",\"\\u062f\\u0639\\u0645 \\u0643\\u0627\\u0645\\u0644 \\u0644\\u0644\\u0627\\u062a\\u062c\\u0627\\u0647\\u064a\\u0646 RTL \\u0648 LTR\"]', 'Admin Dashboard', 'لوحة تحكم إدارية احترافية تتضمن مخططات بيانية وجداول بيانات متقدمة.', '/assets/dashforge-card.png', '/assets/dashforge.png', '[\"\\/assets\\/dashforge.png\",\"\\/assets\\/dashforge-card.png\"]', 1, 1, '0.00', '1.0.0', 'Free for Personal & Commercial Use', 0, '0.0', 0, '2026-09-05 18:54:41', 'published', NULL, '2026-09-08 18:54:41', '2026-09-11 23:29:01'),
(5, 2, 'Finance Planner', 'مخطط الميزانية والمالية - إكسيل', 'finance-planner', 'excel', NULL, 'Microsoft Excel, Google Sheets', 'Business Finance Planner — ready to customize and download in multiple formats and qualities.', '<p>قالب إكسيل متقدم ومعد بمعادلات تلقائية لمتابعة التدفقات النقدية، المصروفات، والادخار للشركات والأفراد.</p>', NULL, '[\"\\u0645\\u0639\\u0627\\u062f\\u0644\\u0627\\u062a \\u062d\\u0633\\u0627\\u0628\\u064a\\u0629 \\u062a\\u0644\\u0642\\u0627\\u0626\\u064a\\u0629\",\"\\u0631\\u0633\\u0648\\u0645 \\u0628\\u064a\\u0627\\u0646\\u064a\\u0629 \\u062a\\u062d\\u0644\\u064a\\u0644\\u064a\\u0629 \\u0644\\u0644\\u0645\\u0635\\u0627\\u0631\\u064a\\u0641\",\"\\u0633\\u0647\\u0648\\u0644\\u0629 \\u0627\\u0644\\u062a\\u0639\\u062f\\u064a\\u0644 \\u0648\\u0627\\u0644\\u062a\\u062e\\u0635\\u064a\\u0635\",\"\\u0645\\u062a\\u0648\\u0627\\u0641\\u0642 \\u0645\\u0639 \\u0625\\u0643\\u0633\\u064a\\u0644 \\u0648\\u062c\\u0648\\u062c\\u0644 \\u0634\\u064a\\u062a\\u0633\"]', 'Business Finance Planner', 'جدول إكسيل احترافي لحساب المصاريف والإيرادات والتخطيط المالي الشهري.', '/assets/shopmart-card.png', NULL, NULL, 0, 1, '0.00', '1.0.0', 'Free for Personal & Commercial Use', 0, '0.0', 0, '2026-09-04 18:54:41', 'published', NULL, '2026-09-08 18:54:41', '2026-09-11 23:29:01'),
(6, 2, 'Invoice Pro', 'إنفويس برو - نموذج فواتير احترافية إكسيل', 'invoice-pro', 'excel', NULL, 'Microsoft Excel (.xlsx)', 'Professional Invoice Template — ready to customize and download in multiple formats and qualities.', '<p>نموذج فواتير رسمي وأنيق مصمم بالمعادلات لحساب الضرائب والخصومات تلقائياً بضغطة زر واحدة.</p>', NULL, '[\"\\u062d\\u0633\\u0627\\u0628 \\u0627\\u0644\\u0636\\u0631\\u0627\\u0626\\u0628 \\u0648\\u0627\\u0644\\u062e\\u0635\\u0648\\u0645\\u0627\\u062a \\u0622\\u0644\\u064a\\u0627\\u064b\",\"\\u062a\\u0635\\u0645\\u064a\\u0645 \\u0631\\u0633\\u0645\\u064a \\u0623\\u0646\\u064a\\u0642 \\u062c\\u0627\\u0647\\u0632 \\u0644\\u0644\\u0637\\u0628\\u0627\\u0639\\u0629\",\"\\u062f\\u0639\\u0645 \\u0625\\u0636\\u0627\\u0641\\u0629 \\u0634\\u0639\\u0627\\u0631 \\u0627\\u0644\\u0634\\u0631\\u0643\\u0629\",\"\\u0645\\u062a\\u0648\\u0627\\u0641\\u0642 \\u0645\\u0639 \\u0643\\u0627\\u0641\\u0629 \\u0627\\u0644\\u0625\\u0635\\u062f\\u0627\\u0631\\u0627\\u062a\"]', 'Professional Invoice Template', 'نموذج فاتورة ضريبية وتجارية جاهزة للطباعة والتصدير كملف PDF.', '/assets/dashforge-card.png', NULL, NULL, 0, 1, '0.00', '1.0.0', 'Free for Personal & Commercial Use', 0, '0.0', 0, '2026-09-03 18:54:41', 'published', NULL, '2026-09-08 18:54:41', '2026-09-11 23:29:01'),
(7, 3, 'Business Letter Pack', 'حزمة الخطابات والنماذج الرسمية - وورد', 'business-letter-pack', 'word', NULL, 'Microsoft Word (.docx)', 'Professional Word Templates — ready to customize and download in multiple formats and qualities.', '<p>حزمة متكاملة من قوالب مايكروسوفت وورد المنسقة بأعلى معايير التنسيق المكتبي لتسهيل المراسلات الإدارية والتجارية.</p>', NULL, '[\"\\u062a\\u0646\\u0633\\u064a\\u0642 \\u0631\\u0633\\u0645\\u064a \\u0645\\u0639\\u062a\\u0645\\u062f\",\"\\u0633\\u0647\\u0648\\u0644\\u0629 \\u062a\\u0639\\u062f\\u064a\\u0644 \\u0627\\u0644\\u0646\\u0635\\u0648\\u0635 \\u0648\\u0627\\u0644\\u062e\\u0637\\u0648\\u0637\",\"\\u062c\\u0627\\u0647\\u0632\\u0629 \\u0644\\u0644\\u0637\\u0628\\u0627\\u0639\\u0629 A4\",\"\\u0645\\u062a\\u0648\\u0627\\u0641\\u0642\\u0629 \\u0645\\u0639 Microsoft Word\"]', 'Professional Word Templates', 'مجموعة خطابات رسمية وعقود ونماذج مراسلات للشركات بصيغة وورد.', '/assets/portfoliox-card.png', NULL, NULL, 0, 1, '0.00', '1.0.0', 'Free for Personal & Commercial Use', 0, '0.0', 0, '2026-09-02 18:54:41', 'published', NULL, '2026-09-08 18:54:41', '2026-09-11 23:29:01'),
(8, 4, 'Social Media Kit', 'حزمة تصاميم السوشيال ميديا - فوتوشوب وفايجما', 'social-media-kit', 'design', NULL, 'Figma, Adobe Photoshop', 'Social Media Design Pack — ready to customize and download in multiple formats and qualities.', '<p>حزمة جرافيك متكاملة تتضمن بوستات وستوريات بتصاميم عصرية واحترافية لجذب العملاء وزيادة التفاعل.</p>', NULL, '[\"\\u0623\\u0643\\u062b\\u0631 \\u0645\\u0646 50 \\u0646\\u0645\\u0648\\u0630\\u062c \\u0645\\u0646\\u0634\\u0648\\u0631 \\u062c\\u0627\\u0647\\u0632\",\"\\u0637\\u0628\\u0642\\u0627\\u062a \\u0645\\u0646\\u0638\\u0645\\u0629 \\u0648\\u0645\\u0633\\u0645\\u0627\\u0629 \\u0628\\u062f\\u0642\\u0629\",\"\\u062e\\u0637\\u0648\\u0637 \\u0648\\u0623\\u0644\\u0648\\u0627\\u0646 \\u0639\\u0635\\u0631\\u064a\\u0629 \\u0642\\u0627\\u0628\\u0644\\u0629 \\u0644\\u0644\\u062a\\u063a\\u064a\\u064a\\u0631\",\"\\u0645\\u0642\\u0627\\u0633\\u0627\\u062a \\u0642\\u064a\\u0627\\u0633\\u064a\\u0629 \\u0644\\u0645\\u0646\\u0635\\u0627\\u062a \\u0627\\u0644\\u062a\\u0648\\u0627\\u0635\\u0644\"]', 'Social Media Design Pack', 'أكثر من 50 تصميماً لمنشورات وبوستات انستغرام وفيسبوك قابلة للتعديل.', '/assets/saaspro-card.png', NULL, NULL, 0, 1, '0.00', '1.0.0', 'Free for Personal & Commercial Use', 0, '0.0', 0, '2026-09-01 18:54:41', 'published', NULL, '2026-09-08 18:54:41', '2026-09-11 23:29:01'),
(9, 5, 'Pitch Deck Pro', 'بيتش ديك برو - عرض تقديمي للشركات الناشئة', 'pitch-deck-pro', 'presentation', NULL, 'PowerPoint (.pptx), Google Slides', 'Modern Business Presentation — ready to customize and download in multiple formats and qualities.', '<p>قالب عروض تقديمية يضم أكثر من 40 شريحة مصممة بعناية لمساعدة رواد الأعمال على تقديم مشاريعهم بنجاح.</p>', NULL, '[\"\\u0623\\u0643\\u062b\\u0631 \\u0645\\u0646 40 \\u0634\\u0631\\u064a\\u062d\\u0629 \\u0641\\u0631\\u064a\\u062f\\u0629\",\"\\u0645\\u062e\\u0637\\u0637\\u0627\\u062a \\u0648\\u0631\\u0633\\u0648\\u0645 \\u062a\\u0648\\u0636\\u064a\\u062d\\u064a\\u0629 \\u0627\\u062d\\u062a\\u0631\\u0627\\u0641\\u064a\\u0629\",\"\\u0631\\u0633\\u0648\\u0645 \\u0645\\u062a\\u062d\\u0631\\u0643\\u0629 \\u0648\\u0627\\u0646\\u062a\\u0642\\u0627\\u0644\\u0627\\u062a \\u0646\\u0627\\u0639\\u0645\\u0629\",\"\\u062a\\u063a\\u064a\\u064a\\u0631 \\u0627\\u0644\\u0623\\u0644\\u0648\\u0627\\u0646 \\u0628\\u0646\\u0642\\u0631\\u0629 \\u0648\\u0627\\u062d\\u062f\\u0629\"]', 'Modern Business Presentation', 'قالب بوربوينت احترافي ومبتكر لعرض المشاريع أمام المستثمرين والعملاء.', '/assets/travelix-card.png', NULL, NULL, 0, 1, '0.00', '1.0.0', 'Free for Personal & Commercial Use', 0, '0.0', 0, '2026-08-31 18:54:41', 'published', NULL, '2026-09-08 18:54:41', '2026-09-11 23:29:01'),
(10, 1, 'Homezy', 'هومزي - قالب موقع عقارات وعقارات فاخرة', 'homezy', 'website', NULL, 'HTML5, CSS3, JavaScript', '<p>Elegant real estate website template. Ready to customize and deploy.</p>', '<p>هومزي يقدم تجربة ممتازة لتصفح العقارات، الخرائط التفاعلية، ومعارض الصور للوحدات السكنية والتجارية.</p>', '[\"Features List (English - One per line)<\\/label>\",\"<textarea class=\\\"input\\\" style=\\\"width:100%;height:90px;padding:8px;line-height:1.6\\\" name=\\\"features_raw\\\"\",\"placeholder=\\\"Fully Responsive Design\",\"Dark and Light Mode\",\"Easy Customization\",\"Commercial License Allowed\\\">\"]', '[\"\\u0641\\u0644\\u062a\\u0631 \\u0648\\u0628\\u062d\\u062b \\u0639\\u0642\\u0627\\u0631\\u064a \\u0645\\u062a\\u0642\\u062f\\u0645\",\"\\u0645\\u0639\\u0631\\u0636 \\u0635\\u0648\\u0631 \\u0639\\u0627\\u0644\\u064a \\u0627\\u0644\\u062f\\u0642\\u0629\",\"\\u0646\\u0645\\u0648\\u0630\\u062c \\u0627\\u0644\\u062a\\u0648\\u0627\\u0635\\u0644 \\u0648\\u062d\\u062c\\u0632 \\u0627\\u0644\\u0645\\u0639\\u0627\\u064a\\u0646\\u0629\",\"\\u0645\\u062a\\u062c\\u0627\\u0648\\u0628 \\u062a\\u0645\\u0627\\u0645\\u0627\\u064b \\u0645\\u0639 \\u0627\\u0644\\u0647\\u0648\\u0627\\u062a\\u0641\"]', 'Elegant real estate website template.', 'قالب متطور لمكاتب وشركات التسويق العقاري والبحث عن العقارات.', '/assets/homezy-card.png', NULL, NULL, 0, 1, '0.00', '1.0.0', 'Free for Personal & Commercial Use', 9300, '4.6', 0, '2026-09-08 21:27:04', 'published', NULL, '2026-09-08 21:27:04', '2026-09-13 00:36:00'),
(11, 1, 'PortfolioX', 'بورتفوليو إكس - قالب معرض أعمال شخصي', 'portfoliox', 'website', NULL, 'Next.js 15, Tailwind CSS', 'Minimal portfolio for designers and developers. Ready to customize and deploy.', '<p>بورتفوليو إكس يمنحك حضوراً رقمياً جذاباً لعرض أعمالك السابقة، خبراتك، وآراء عملائك بطريقة ملهمة.</p>', NULL, '[\"\\u0648\\u0636\\u0639 \\u0644\\u064a\\u0644\\u064a \\u0648\\u0646\\u0647\\u0627\\u0631\\u064a \\u0645\\u062f\\u0645\\u062c\",\"\\u0645\\u0639\\u0631\\u0636 \\u0645\\u0634\\u0627\\u0631\\u064a\\u0639 \\u062f\\u064a\\u0646\\u0627\\u0645\\u064a\\u0643\\u064a\",\"\\u0646\\u0645\\u0648\\u0630\\u062c \\u0627\\u062a\\u0635\\u0627\\u0644 \\u0633\\u0631\\u064a\\u0639\",\"\\u0633\\u0631\\u0639\\u0629 \\u062a\\u062d\\u0645\\u064a\\u0644 \\u0641\\u0627\\u0626\\u0642\\u0629 \\u0648\\u0645\\u062a\\u0648\\u0627\\u0641\\u0642 \\u0645\\u0639 SEO\"]', 'Minimal portfolio for designers and developers.', 'قالب شخصي أنيق للمطورين والمصممين المستقلين لعرض المشاريع والمهارات.', '/assets/portfoliox-card.png', NULL, NULL, 0, 1, '0.00', '1.0.0', 'Free for Personal & Commercial Use', 6700, '4.8', 0, '2026-09-08 21:27:04', 'published', NULL, '2026-09-08 21:27:04', '2026-09-11 23:29:01'),
(12, 1, 'BlogMart', 'بلوج مارت - قالب مدونة ومجلة إلكترونية', 'blogmart', 'website', NULL, 'HTML5, Tailwind CSS', 'Editorial blog and magazine template. Ready to customize and deploy.', '<p>بلوج مارت مصمم لتوفير تجربة قراءة مريحة للمقالات، مع دعم الإعلانات ومشاركة المنشورات على منصات التواصل.</p>', NULL, '[\"\\u0647\\u064a\\u0643\\u0644\\u0629 \\u0645\\u0642\\u0627\\u0644\\u0627\\u062a \\u0645\\u0631\\u064a\\u062d\\u0629 \\u0644\\u0644\\u0642\\u0631\\u0627\\u0621\\u0629\",\"\\u062a\\u0648\\u0632\\u064a\\u0639 \\u0645\\u062a\\u0646\\u0627\\u0633\\u0642 \\u0644\\u0644\\u0623\\u0642\\u0633\\u0627\\u0645 \\u0648\\u0627\\u0644\\u0645\\u0648\\u0627\\u0636\\u064a\\u0639\",\"\\u0623\\u0645\\u0627\\u0643\\u0646 \\u0645\\u062e\\u0635\\u0635\\u0629 \\u0644\\u0644\\u0628\\u0646\\u0631\\u0627\\u062a \\u0627\\u0644\\u0625\\u0639\\u0644\\u0627\\u0646\\u064a\\u0629\",\"\\u0645\\u062a\\u0648\\u0627\\u0641\\u0642 \\u0645\\u0639 \\u0645\\u0639\\u0627\\u064a\\u064a\\u0631 SEO\"]', 'Editorial blog and magazine template.', 'قالب مدونة ومجلة إخبارية عصري سريع ومتوافق مع محركات البحث.', '/assets/blogmart-card.png', NULL, NULL, 0, 1, '0.00', '1.0.0', 'Free for Personal & Commercial Use', 4900, '4.5', 0, '2026-09-08 21:27:04', 'published', NULL, '2026-09-08 21:27:04', '2026-09-11 23:29:01'),
(13, 1, 'Resto', 'ريستو - قالب مطاعم وكافيهات فاخرة', 'resto', 'website', NULL, 'HTML5, CSS3, JavaScript', 'Premium restaurant and food website template. Ready to customize and deploy.', '<p>ريستو يتميز بتصميم شهي وأنيق لعرض أطباق المطعم، الأسعار، وحجز الطاولات أونلاين بكل سهولة.</p>', NULL, '[\"\\u0645\\u0646\\u064a\\u0648 \\u0637\\u0639\\u0627\\u0645 \\u062a\\u0641\\u0627\\u0639\\u0644\\u064a \\u0648\\u0645\\u0635\\u0648\\u0631\",\"\\u0646\\u0638\\u0627\\u0645 \\u062d\\u062c\\u0632 \\u0637\\u0627\\u0648\\u0644\\u0627\\u062a \\u0633\\u0631\\u064a\\u0639\",\"\\u062e\\u0631\\u064a\\u0637\\u0629 \\u062a\\u0641\\u0627\\u0639\\u0644\\u064a\\u0629 \\u0648\\u0633\\u0627\\u0639\\u0627\\u062a \\u0627\\u0644\\u0639\\u0645\\u0644\",\"\\u062a\\u0635\\u0645\\u064a\\u0645 \\u0645\\u062a\\u062c\\u0627\\u0648\\u0628 \\u0645\\u062e\\u0635\\u0635 \\u0644\\u0644\\u0645\\u0648\\u0628\\u0627\\u064a\\u0644\"]', 'Premium restaurant and food website template.', 'قالب جذاب للمطاعم والكافيهات مع قائمة طعام ونظام حجز طاولات.', '/assets/resto-card.png', NULL, NULL, 0, 1, '0.00', '1.0.0', 'Free for Personal & Commercial Use', 7100, '4.7', 0, '2026-09-08 21:27:04', 'published', NULL, '2026-09-08 21:27:04', '2026-09-11 23:29:01');
