(14, 'footer_columns', '[{\"title\":\"Quick Links\",\"title_ar\":\"روابط سريعة\",\"links\":[{\"label\":\"Home\",\"label_ar\":\"الرئيسية\",\"url\":\"\\/\"},{\"label\":\"Templates\",\"label_ar\":\"القوالب والتصاميم\",\"url\":\"\\/templates\"},{\"label\":\"Categories\",\"label_ar\":\"الأقسام والتصنيفات\",\"url\":\"\\/categories\"},{\"label\":\"Blog\",\"label_ar\":\"المدونة والمقالات\",\"url\":\"\\/blog\"},{\"label\":\"Services\",\"label_ar\":\"الخدمات والحلول\",\"url\":\"\\/services\"},{\"label\":\"About Us\",\"label_ar\":\"من نحن\",\"url\":\"\\/about\"}]},{\"title\":\"Resources\",\"title_ar\":\"الموارد والقوالب\",\"links\":[{\"label\":\"Freebies\",\"label_ar\":\"قوالب مجانية\",\"url\":\"\\/templates?price=Free\"},{\"label\":\"UI Kits\",\"label_ar\":\"حزم واجهات المستخدم\",\"url\":\"\\/templates?cat=UI+Kit\"},{\"label\":\"Excel Templates\",\"label_ar\":\"قوالب إكسيل\",\"url\":\"\\/templates?type=Excel\"},{\"label\":\"Word Templates\",\"label_ar\":\"قوالب وورد\",\"url\":\"\\/templates?type=Word\"},{\"label\":\"Design Resources\",\"label_ar\":\"تصاميم وجرافيك\",\"url\":\"\\/templates?type=Design\"},{\"label\":\"Documentation\",\"label_ar\":\"الشروحات والمقالات\",\"url\":\"\\/blog\"}]},{\"title\":\"Help & Support\",\"title_ar\":\"المساعدة والدعم\",\"links\":[{\"label\":\"FAQ\",\"label_ar\":\"الأسئلة الشائعة\",\"url\":\"\\/faq\"},{\"label\":\"Custom Requests\",\"label_ar\":\"طلب تخصيص قالب\",\"url\":\"\\/custom-requests\"},{\"label\":\"Technical Support\",\"label_ar\":\"الدعم الفني\",\"url\":\"\\/support\"},{\"label\":\"Contact Us\",\"label_ar\":\"تواصل معنا\",\"url\":\"\\/contact\"},{\"label\":\"Privacy Policy\",\"label_ar\":\"سياسة الخصوصية\",\"url\":\"\\/privacy\"},{\"label\":\"Terms of Service\",\"label_ar\":\"شروط الاستخدام\",\"url\":\"\\/terms\"}]}]', 'json', '2026-09-08 21:27:04', '2026-09-13 00:27:53'),
(15, 'home_hero', '{\"eyebrow\":\"Free & Premium Website Templates\",\"title\":\"Beautiful Templates\",\"highlight_text\":\"for Every Project\",\"lead\":\"Discover thousands of free and premium website templates, UI kits, and design resources. Download, customize, and build your next amazing project faster.\",\"hero_image\":\"\\/assets\\/hero-main.png\",\"note_title\":\"Your Next Website\",\"note_subtitle\":\"Starts Here\",\"stat_badge_1_val\":\"1000+\",\"stat_badge_1_label\":\"Free Templates\",\"stat_badge_2_val\":\"Modern\",\"stat_badge_2_label\":\"& Responsive\",\"stat_badge_3_val\":\"⚡ Easy to\",\"stat_badge_3_label\":\"Customize\"}', 'json', '2026-09-08 21:27:04', '2026-09-08 21:27:04'),
(16, 'home_popular_tags', '[\"Laravel\",\"Next.js\",\"Admin Dashboard\",\"eCommerce\",\"Portfolio\",\"Blog\",\"React\",\"Tailwind\"]', 'json', '2026-09-08 21:27:04', '2026-09-08 21:27:04'),
(17, 'home_featured_section', '{\"eyebrow\":\"Featured Templates\",\"title\":\"Trending Templates\",\"description\":\"Hand-picked templates to help you build faster.\",\"button_text\":\"View All Templates →\",\"button_url\":\"\\/templates\"}', 'json', '2026-09-08 21:27:04', '2026-09-08 21:27:04'),
(18, 'home_benefits', '[{\"icon\":\"Zap\",\"title\":\"100% Free Options\",\"description\":\"High-quality templates completely free to download and kickstart your work.\"},{\"icon\":\"MonitorCog\",\"title\":\"Responsive Design\",\"description\":\"Works perfectly on all modern devices, tablets, and desktop screen sizes.\"},{\"icon\":\"Settings2\",\"title\":\"Easy to Customize\",\"description\":\"Clean, structured, and well-documented code designed for rapid editing.\"},{\"icon\":\"Users\",\"title\":\"Trusted by Developers\",\"description\":\"Join thousands of developers and creators worldwide building with EzyTemplate.\"}]', 'json', '2026-09-08 21:27:04', '2026-09-08 21:27:04'),
(19, 'home_cta', '{\"title\":\"Ready to Build Something Amazing?\",\"description\":\"Join our community and get access to the latest templates, updates, and resources.\",\"button_text\":\"Get Started for Free →\",\"button_url\":\"\\/templates\"}', 'json', '2026-09-08 21:27:04', '2026-09-08 21:27:04'),
(20, 'about_hero', '{\"eyebrow\":\"About Us\",\"title\":\"We Empower\",\"highlight_text\":\"Creators & Builders\",\"lead\":\"At EzyTemplate, we believe everyone can build something amazing. We provide high-quality, free and premium website templates, UI kits, and resources to help developers, designers, and businesses bring their ideas to life faster.\",\"hero_image\":\"\\/assets\\/about-hero.png\",\"btn_primary_text\":\"Explore Templates →\",\"btn_primary_url\":\"\\/templates\",\"btn_secondary_text\":\"Join Our Community\",\"btn_secondary_url\":\"\\/signup\"}', 'json', '2026-09-08 21:27:04', '2026-09-08 21:27:04'),
(21, 'about_stats', '[{\"icon\":\"Download\",\"count\":\"1000+\",\"label\":\"Templates Available\"},{\"icon\":\"Users\",\"count\":\"50K+\",\"label\":\"Happy Users\"},{\"icon\":\"Star\",\"count\":\"4.9\\/5\",\"label\":\"Average Rating\"},{\"icon\":\"Globe\",\"count\":\"150+\",\"label\":\"Countries\"}]', 'json', '2026-09-08 21:27:04', '2026-09-08 21:27:04'),
(22, 'about_story', '{\"eyebrow\":\"Our Story\",\"title\":\"A Passion for Better Web Experiences\",\"image\":\"\\/assets\\/about-story.png\",\"paragraph_1\":\"EzyTemplate started as a small idea between a group of developers and designers who wanted to make high-quality templates accessible to everyone. We noticed that many amazing resources were either too expensive or hard to find, so we decided to create a platform that brings everything together in one place.\",\"paragraph_2\":\"Today, EzyTemplate is a growing community of creators, learners, and businesses who trust us for modern, clean, and easy-to-use templates across various technologies and formats.\"}', 'json', '2026-09-08 21:27:04', '2026-09-08 21:27:04'),
(23, 'about_values', '[{\"icon\":\"Target\",\"title\":\"Our Mission\",\"description\":\"To simplify website development and design for everyone everywhere.\"},{\"icon\":\"Eye\",\"title\":\"Our Vision\",\"description\":\"A world where high-quality web design and code is accessible to all creators.\"},{\"icon\":\"Heart\",\"title\":\"Our Values\",\"description\":\"Quality, community support, creativity, transparency, and continuous improvement.\"}]', 'json', '2026-09-08 21:27:04', '2026-09-08 21:27:04'),
(24, 'about_team', '[{\"name\":\"Mohamed Ramadan\",\"name_ar\":\"محمد رمضان\",\"role\":\"Software Engineer\",\"role_ar\":\"مهندس برمجيات\",\"bio\":\"Software Engineer specialized in full-stack web development, building high-performance scalable systems and modern digital platforms.\",\"bio_ar\":\"مهندس برمجيات متخصص في تطوير الويب الشامل والحلول البرمجية عالية الأداء وبناء المنصات الرقمية الحديثة.\",\"image\":\"\\/assets\\/mohamed-ramadan.png\",\"linkedin\":\"http:\\/\\/linkedin.com\\/in\\/mohamed-ramadan-zaki\\/\",\"facebook\":\"https:\\/\\/www.facebook.com\\/profile.php?id=61589459066799\"}]', 'json', '2026-09-08 21:27:04', '2026-09-12 18:52:26'),
(25, 'about_cta', '{\"title\":\"Join Our Growing Community\",\"description\":\"Be part of thousands of developers and designers. Get updates, free resources, and inspiration directly in your inbox.\",\"button_text\":\"Get Started →\",\"button_url\":\"\\/signup\"}', 'json', '2026-09-08 21:27:04', '2026-09-08 21:27:04'),
(26, 'services_hero', '{\"eyebrow\":\"Our Services\",\"title\":\"More Than Templates\",\"highlight_text\":\"We Help You Build\",\"lead\":\"From customization to full website development, EzyTemplate offers professional services to help you launch, customize, and grow your online projects.\",\"hero_image\":\"\\/assets\\/services-hero.png\",\"btn_primary_text\":\"Get Started →\",\"btn_primary_url\":\"#request-service\",\"btn_secondary_text\":\"Explore FAQs\",\"btn_secondary_url\":\"#faq\"}', 'json', '2026-09-08 21:27:04', '2026-09-08 21:27:04'),
(27, 'services_trust_badges', '[{\"icon\":\"ShieldCheck\",\"title\":\"Trusted & Reliable\",\"subtitle\":\"Quality work delivered on time\"},{\"icon\":\"Zap\",\"title\":\"Fast Delivery\",\"subtitle\":\"Get your project done quickly\"},{\"icon\":\"Award\",\"title\":\"Satisfaction Guarantee\",\"subtitle\":\"We\'re not happy until you are\"}]', 'json', '2026-09-08 21:27:04', '2026-09-08 21:27:04'),
(28, 'services_list', '[{\"icon\":\"Settings\",\"title\":\"Template Customization\",\"description\":\"Need changes to a template? We customize colors, structure, and features to match your brand and exact requirements.\"},{\"icon\":\"Code2\",\"title\":\"Full Website Development\",\"description\":\"Get a complete bespoke website built using our templates or from scratch with full backend and database integration.\"},{\"icon\":\"Smartphone\",\"title\":\"Website Conversion\",\"description\":\"Convert Figma or static designs to production-ready Laravel, Next.js, React or HTML\\/Tailwind.\"},{\"icon\":\"Paintbrush\",\"title\":\"UI\\/UX Design\",\"description\":\"Get modern, conversion-focused design systems for your website, SaaS dashboard, or mobile web application.\"},{\"icon\":\"LifeBuoy\",\"title\":\"Installation & Setup\",\"description\":\"We will deploy, install and configure your template or full-stack application on your server or cloud host.\"},{\"icon\":\"Users\",\"title\":\"Ongoing Maintenance & Support\",\"description\":\"Continuous updates, bug fixing, performance enhancements, and technical support whenever you need it.\"}]', 'json', '2026-09-08 21:27:04', '2026-09-08 21:27:04'),
(29, 'services_why_us', '{\"eyebrow\":\"Why Choose Us\",\"title\":\"Your Success is Our Priority\",\"lead\":\"We combine technical expertise, creative design, and reliable support to deliver the best solutions for your web projects.\",\"image\":\"\\/assets\\/services-why.png\",\"bullets\":[\"Experienced Senior Developers & Designers\",\"Pixel-Perfect and High-Quality Code\",\"Strict On-Time Delivery Deadlines\",\"Clear and Transparent Communication\",\"Competitive and Affordable Pricing\"]}', 'json', '2026-09-08 21:27:04', '2026-09-08 21:27:04'),
(30, 'services_process', '[{\"step\":1,\"title\":\"Tell Us What You Need\",\"description\":\"Fill out our quick service request form with your project specifications and requirements.\"},{\"step\":2,\"title\":\"Get a Custom Quote\",\"description\":\"We review your needs and provide a tailored plan with accurate timeline and cost.\"},{\"step\":3,\"title\":\"We Get To Work\",\"description\":\"Our developers and designers craft your solution with regular updates along the way.\"},{\"step\":4,\"title\":\"Delivery & Support\",\"description\":\"We deploy your project and provide warranty support to ensure everything runs smoothly.\"}]', 'json', '2026-09-08 21:27:04', '2026-09-08 21:27:04'),
(31, 'services_faqs', '[{\"question\":\"How much does a custom website or template modification cost?\",\"answer\":\"Pricing depends on project scope, complexity, and timeline. Minor template customizations start at very affordable rates, while full-stack applications are quoted based on requirements.\"},{\"question\":\"How long does it take to complete a project?\",\"answer\":\"Small customizations take 1-3 business days. Full custom websites usually take between 1 to 3 weeks depending on the number of pages and integrations.\"},{\"question\":\"Do you provide support and revisions after delivery?\",\"answer\":\"Yes, every service package includes post-delivery revision rounds and a warranty period to fix any issues.\"},{\"question\":\"Can you work with my existing design files or code?\",\"answer\":\"Absolutely! We work with Figma, Adobe XD, Sketch, Photoshop, or any existing repository you provide.\"},{\"question\":\"What technologies and frameworks do you specialize in?\",\"answer\":\"We specialize in Laravel, PHP, Next.js, React, Tailwind CSS, Bootstrap, TypeScript, Node.js, and WordPress.\"}]', 'json', '2026-09-08 21:27:04', '2026-09-08 21:27:04'),
(32, 'services_help_box', '{\"title\":\"Still Have Questions?\",\"description\":\"We\'re here to help. Send us your project details and our team will get back to you within 24 hours.\",\"button_text\":\"Request a Quote →\",\"button_url\":\"#request-service\"}', 'json', '2026-09-08 21:27:04', '2026-09-08 21:27:04'),
(33, 'page_faq', '{\"title\":\"Frequently Asked Questions\",\"title_ar\":\"الأسئلة الشائعة\",\"subtitle\":\"Find quick answers to common questions about downloads, licenses, and customizations.\",\"subtitle_ar\":\"إليك إجابات سريعة لأكثر الأسئلة تكراراً حول التحميلات، التراخيص، والتعديلات.\",\"items\":[{\"category\":\"General\",\"category_ar\":\"عام\",\"question\":\"Are the templates on EzyTemplate free to use?\",\"question_ar\":\"هل القوالب المتاحة على إيزي ستور مجانية؟\",\"answer\":\"Yes! We offer a vast collection of 100% free templates for personal and commercial projects, as well as premium templates with extended features.\",\"answer_ar\":\"نعم! نوفر مجموعة ضخمة من القوالب المجانية 100% للاستخدام الشخصي والتجاري، بالإضافة لقوالب مدفوعة ذات ميزات متقدمة.\"},{\"category\":\"Licensing\",\"category_ar\":\"التراخيص\",\"question\":\"Can I use downloaded templates for client projects?\",\"question_ar\":\"هل يمكنني استخدام القوالب المحملة لمشاريع عملائي؟\",\"answer\":\"Absolutely. All our free and premium templates include commercial usage rights for client websites and business projects.\",\"answer_ar\":\"بالتأكيد. جميع القوالب المجانية والمدفوعة تمنحك حق الاستخدام التجاري لمشاريع عملائك وشركتك.\"},{\"category\":\"Downloads\",\"category_ar\":\"التحميلات\",\"question\":\"What file formats are included with downloads?\",\"question_ar\":\"ما هي صيغ الملفات المرفقة مع القوالب؟\",\"answer\":\"Depending on the template, files include HTML5, Tailwind CSS, Next.js, Figma design files, Excel spreadsheets (.xlsx), or Word documents (.docx).\",\"answer_ar\":\"حسب نوع القالب، تشمل الملفات: HTML5، Tailwind CSS، Next.js، ملفات تصاميم Figma، جداول Excel (.xlsx)، أو مستندات Word (.docx).\"},{\"category\":\"Support\",\"category_ar\":\"الدعم الفني\",\"question\":\"How can I request custom edits for a template?\",\"question_ar\":\"كيف يمكنني طلب تعديلات خاصة على قالب معين؟\",\"answer\":\"You can submit a custom request through our Custom Requests page or Contact form. Our engineering team will assist you promptly.\",\"answer_ar\":\"يمكنك تقديم طلب تخصيص عبر صفحة طلب قالب مخصص أو نموذج التواصل، وسيقوم فريقنا البرمجي بمساعدتك فوراً.\"}]}', 'json', '2026-09-13 00:27:53', '2026-09-13 00:27:53'),
(34, 'page_custom_requests', '{\"title\":\"Custom Template & Development Requests\",\"title_ar\":\"طلب تخصيص قالب أو مشروع خاص\",\"subtitle\":\"Need a tailored website, custom Excel dashboard, or custom UI design? Send us your project details.\",\"subtitle_ar\":\"هل تحتاج لتطوير موقع خاص، لوحة إكسيل مخصصة، أو تصميم واجهات احترافي؟ أرسل لنا تفاصيل مشروعك.\",\"info_email\":\"custom@ezytemplate.com\",\"delivery_time\":\"24 - 48 Hours SLA\",\"delivery_time_ar\":\"الرد والتقدير خلال 24 - 48 ساعة\"}', 'json', '2026-09-13 00:27:53', '2026-09-13 00:27:53'),
(35, 'page_support', '{\"title\":\"Technical Support Center\",\"title_ar\":\"مركز الدعم الفني والخدمات\",\"subtitle\":\"We are here to help you solve technical issues, file extract errors, and installation questions.\",\"subtitle_ar\":\"نحن هنا لمساعدتك في حل أي مشكلات تقنية، فك الضغط عن الملفات، أو استفسارات التثبيت.\",\"support_email\":\"support@ezytemplate.com\",\"sla_hours\":\"24 Hours Response Guarantee\",\"sla_hours_ar\":\"ضمان الرد خلال 24 ساعة\"}', 'json', '2026-09-13 00:27:53', '2026-09-13 00:27:53'),
(36, 'page_contact', '{\"title\":\"Contact Us\",\"title_ar\":\"تواصل معنا\",\"subtitle\":\"Have a question or feedback? Reach out to our team anytime.\",\"subtitle_ar\":\"لديك استفسار أو اقتراح؟ تواصل مع فريقنا في أي وقت.\",\"email\":\"support@ezytemplate.com\",\"phone\":\"+20 100 000 0000\",\"address\":\"Cairo, Egypt\",\"address_ar\":\"القاهرة، مصر\",\"working_hours\":\"Sun - Thu: 9:00 AM - 6:00 PM (GMT+2)\",\"working_hours_ar\":\"الأحد - الخميس: 9:00 صباحاً - 6:00 مساءً\"}', 'json', '2026-09-13 00:27:53', '2026-09-13 00:27:53'),
(37, 'page_privacy', '{\"title\":\"Privacy Policy\",\"title_ar\":\"سياسة الخصوصية\",\"subtitle\":\"Your privacy matters to us. Learn how we collect, protect, and handle your data.\",\"subtitle_ar\":\"خصوصيتك تهمناً جداً. تعرّف على كيفية جمعنا لحمايتنا وتأمين بياناتك.\",\"last_updated\":\"September 2026\",\"last_updated_ar\":\"سبتمبر 2026\",\"content_en\":\"At EzyTemplate, we respect your privacy and are committed to protecting personal information. We only collect essential account information required to provide downloads, support, and authentication. We do not sell or rent personal data to third parties.\",\"content_ar\":\"في إيزي ستور، نحترم خصوصيتك ونلتزم بحماية بياناتك الشخصية. نجمع فقط البيانات الأساسية اللازمة لتقديم خدمات التحميل، الدعم الفني، وإنشاء الحسابات. لا نقوم ببيع أو مشاركة بياناتك مع أي طرف ثالث.\"}', 'json', '2026-09-13 00:27:53', '2026-09-13 00:27:53'),
(38, 'page_terms', '{\"title\":\"Terms of Service\",\"title_ar\":\"شروط الاستخدام والخدمة\",\"subtitle\":\"Read the rules and guidelines governing the use of EzyTemplate resources.\",\"subtitle_ar\":\"اقرأ القواعد والتراخيص المنظمة لاستخدام قوالب وموارد إيزي ستور.\",\"last_updated\":\"September 2026\",\"last_updated_ar\":\"سبتمبر 2026\",\"content_en\":\"By downloading resources from EzyTemplate, you agree to comply with our license terms. Free resources allow personal and commercial website deployment. Redistribution or resale of raw template source files is strictly prohibited.\",\"content_ar\":\"بتحميلك للموارد من إيزي ستور، فإنك توافق على الالتزام بشروط التراخيص. تتيح لك الموارد المجانية إنشاء مشاريع شخصية وتجارية. يُحظر تماماً إعادة بيع أو إعادة توزيع ملفات القوالب البرمجية الأصلية.\"}', 'json', '2026-09-13 00:27:53', '2026-09-13 00:27:53');
