INSERT INTO `main_categories` (`name`,`name_ar`,`slug`,`icon`,`color`,`description`,`description_ar`,`sort_order`,`is_active`,`created_at`,`updated_at`) VALUES ('Excel Templates','قوالب إكسيل','excel-templates','table','#10B981','Editable office templates and source files for practical business use.','قوالب مكتبية وملفات مصدر قابلة للتعديل للاستخدام العملي في الأعمال.',1,1,NOW(),NOW()) ON DUPLICATE KEY UPDATE `name`=VALUES(`name`),`name_ar`=VALUES(`name_ar`),`icon`=VALUES(`icon`),`color`=VALUES(`color`),`updated_at`=NOW();
